<?php declare(strict_types=1);final class TaskDependencyRepository{public function __construct(private mysqli$db){}public function listOwned(int$task,int$u):array{$s=$this->db->prepare('SELECT d.condition,required.public_id depends_on_public_id,required.status depends_on_status FROM TaskDependencies d JOIN Tasks owner ON owner.id_=d.task_id_ JOIN Tasks required ON required.id_=d.depends_on_task_id_ WHERE d.task_id_=? AND owner.user_id_=? AND required.user_id_=? ORDER BY d.id_');if(!$s)throw new RuntimeException('database_error');$s->bind_param('iii',$task,$u,$u);$s->execute();$o=[];$r=$s->get_result();while($x=$r->fetch_assoc())$o[]=$x;$s->close();return$o;}}
